import "sync"

type ContadorSeguro struct {
  mu    sync.Mutex
  valor int
}

func (c *ContadorSeguro) Incrementar() {
  c.mu.Lock()           // adquirir mutex
  defer c.mu.Unlock()   // liberar al salir (defer garantiza esto)
  c.valor++
}

func (c *ContadorSeguro) Leer() int {
  c.mu.Lock()
  defer c.mu.Unlock()
  return c.valor
}

